import React, { useEffect, useState } from 'react'
import {Link} from "react-router-dom";
import './Reports.css'
import axios from "axios";




export default function Reports() {

    const [user, setUser] = useState(null);
    const localUser = JSON.parse(localStorage.getItem('user'));


    const [userRole, setUserRole] = useState(null);
    const [accessData, setAccessData] = useState([]);




    useEffect(() => {
        const getUser = async () => {
            try {
                const response = await axios.get('/api/user/' + localUser._id);
                const roleId = response.data.role_id;
                setUserRole(roleId);

                // Запрашиваем разрешения только после того, как установили роль
                const res = await axios.get('/api/permission/' + roleId);
                console.log('Permissions:', res.data);
                setAccessData(res.data);
            } catch (error) {
                console.error('Error fetching user or permissions:', error);
            }
        };

        getUser();
    }, [localUser._id]);

    const isAccessible = (toolId) => {
        console.log('Checking access for tool:', toolId);
        return accessData.some(permission => permission.tool_id === toolId && permission.is_accessible);
    };

    return (
        <div className="ReportsButton">
            {userRole === null ? (
                <div>Loading...</div>
            ) : (
                <>
                    {isAccessible(2) && <Link to='/ReportsHistory' className='linkReports'>Отчет по истории</Link>}
                    <br/>
                    {isAccessible(3) && <Link to='/ReportsNominations' className='linkReports'>Отчет по номинациям</Link>}
                </>
            )}
        </div>
    );
};
